"""Compile model data and the image attribution page; no network at runtime."""
from pathlib import Path
import json,html
models=json.loads(Path('commerce-models.json').read_text());credits=[];atlas=json.loads(Path('img/commerce/import-illustrations-v1.json').read_text())
for m in models:
 p=Path('img/commerce')/(m['key']+'.webp');meta=p.with_suffix('.json')
 m['photo']=str(p) if p.exists() else ''
 if m['kind']=='import' and m['key'] in atlas['models']:
  art_index=atlas['models'].index(m['key'])
  m['illustration']={'src':atlas['image'],'column':art_index%atlas['columns'],'row':art_index//atlas['columns']}
  m['illustration'].update({k:atlas[k] for k in ['width','height','columns','rows']})
 if meta.exists():credits.append(json.loads(meta.read_text()))
Path('commerce-models.js').write_text("'use strict';\n// Generated by scripts/build-commerce-models.py. Prices and stock are game data.\nvar COMMERCE_MODELS="+json.dumps([{k:v for k,v in m.items() if k in ['key','kind','brand','model','price','engine','body','country','minYear','photo','illustration']} for m in models],ensure_ascii=False,separators=(',',':'))+';\n')
rows=''.join('<tr><td>'+html.escape(c['model'])+'</td><td><a href="'+html.escape(c['source'],quote=True)+'">'+html.escape(c['file'])+'</a></td><td>'+html.escape(c['author'])+'</td><td><a href="'+html.escape(c['licenseUrl'],quote=True)+'">'+html.escape(c['license'])+'</a></td></tr>' for c in credits)
Path('commerce-photo-credits.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>Фотографии моделей — Perekup.ru</title><style>body{font:15px system-ui;max-width:1100px;margin:30px auto;padding:20px}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd;overflow-wrap:anywhere}table{width:100%}</style><h1>Фотографии моделей</h1><p>Снимки моделей используются как иллюстрации. Цвет, комплектация и состояние игрового экземпляра указаны отдельно. Снимки уменьшены и перекодированы в WebP; исходные лицензии сохраняются. Данные каталога и цены являются игровыми. В текущем импорте показаны собственные рисованные иллюстрации, созданные инструментом image_gen; их цвета и детали условны. Атрибуции ниже сохранены для фотографий автосалона и прежних изображений моделей.</p><table><tr><th>Модель</th><th>Источник</th><th>Автор</th><th>Лицензия</th></tr>'+rows+'</table></html>')
print(len(models),'models;',len(credits),'photos')
